import { Container } from 'inversify';
import { TYPES } from './utils/constants.js';
import { AxiosAdapterImpl } from './http/axios-adapter-impl.js';
import { Clients } from './services/get-client-apadter-impl.js';
import { LargestPerimeterTriangle } from '../src/leetCode/largestPerimeterTriangle.js';
import { LargestRectangleOverlap } from '../src/leetCode/rectangleOverlap.js';
const AppContainer = new Container();
AppContainer.bind(TYPES.AxiosAdapter).to(AxiosAdapterImpl);
AppContainer.bind(TYPES.getClientAdapter).to(Clients);
AppContainer.bind(TYPES.LeetCodeRectangleOverlap).to(LargestRectangleOverlap);
AppContainer.bind(TYPES.LeetCodeLargestPerimeterTriangle).to(LargestPerimeterTriangle);
export { AppContainer };
